/**
 * Fires when a line's Line_Status__c transitions to Approved. Resolves the target
 * Public Group's live Id from Country__r.Public_Group_Name__c (never a cached Id),
 * inserts the GroupMember if one doesn't already exist, and upserts the matching
 * User_Country_Access__c row so the current-access list stays reportable.
 */
public without sharing class LSOGroupAccessService {

    private static Set<Id> processedLineIds = new Set<Id>();

    public static void grantAccessForApprovedLines(List<LSO_CCAR_Line__c> newLines, Map<Id, LSO_CCAR_Line__c> oldMap) {
        List<Id> newlyApprovedIds = new List<Id>();
        for (LSO_CCAR_Line__c ln : newLines) {
            LSO_CCAR_Line__c oldLn = oldMap.get(ln.Id);
            Boolean justApproved = ln.Line_Status__c == 'Approved' && oldLn != null && oldLn.Line_Status__c != 'Approved';
            if (justApproved && !processedLineIds.contains(ln.Id)) {
                newlyApprovedIds.add(ln.Id);
                processedLineIds.add(ln.Id);
            }
        }
        if (newlyApprovedIds.isEmpty()) {
            return;
        }

        Map<Id, LSO_CCAR_Line__c> lineMap = new Map<Id, LSO_CCAR_Line__c>([
            SELECT Id, Country__c, Country__r.Public_Group_Name__c,
                   LSO_Cross_Country_Access_Request__r.Requested_User__c
            FROM LSO_CCAR_Line__c
            WHERE Id IN :newlyApprovedIds
        ]);

        Set<String> groupDevNames = new Set<String>();
        Set<Id> candidateUserIds = new Set<Id>();
        for (LSO_CCAR_Line__c ln : lineMap.values()) {
            if (ln.Country__r.Public_Group_Name__c != null) {
                groupDevNames.add(ln.Country__r.Public_Group_Name__c);
            }
            if (ln.LSO_Cross_Country_Access_Request__r.Requested_User__c != null) {
                candidateUserIds.add(ln.LSO_Cross_Country_Access_Request__r.Requested_User__c);
            }
        }

        Map<String, Id> groupIdByDevName = new Map<String, Id>();
        for (Group g : [SELECT Id, DeveloperName FROM Group WHERE DeveloperName IN :groupDevNames]) {
            groupIdByDevName.put(g.DeveloperName, g.Id);
        }

        Set<String> existingMembershipKeys = new Set<String>();
        if (!candidateUserIds.isEmpty() && !groupIdByDevName.isEmpty()) {
            for (GroupMember gm : [
                SELECT GroupId, UserOrGroupId
                FROM GroupMember
                WHERE GroupId IN :groupIdByDevName.values()
                AND UserOrGroupId IN :candidateUserIds
            ]) {
                existingMembershipKeys.add(gm.GroupId + ':' + gm.UserOrGroupId);
            }
        }

        Map<String, User_Country_Access__c> existingAccessByKey = new Map<String, User_Country_Access__c>();
        if (!candidateUserIds.isEmpty()) {
            for (User_Country_Access__c uca : [
                SELECT Id, Requested_User__c, Country__c, Status__c, Source_Line__c
                FROM User_Country_Access__c
                WHERE Requested_User__c IN :candidateUserIds
            ]) {
                existingAccessByKey.put(uca.Requested_User__c + ':' + uca.Country__c, uca);
            }
        }

        List<GroupMember> membersToInsert = new List<GroupMember>();
        List<User_Country_Access__c> accessRowsToUpsert = new List<User_Country_Access__c>();
        List<LSO_CCAR_Line__c> linesToUpdate = new List<LSO_CCAR_Line__c>();

        for (LSO_CCAR_Line__c ln : lineMap.values()) {
            Id userId = ln.LSO_Cross_Country_Access_Request__r.Requested_User__c;
            String devName = ln.Country__r.Public_Group_Name__c;
            Id groupId = (devName != null) ? groupIdByDevName.get(devName) : null;

            if (userId == null || groupId == null) {
                linesToUpdate.add(new LSO_CCAR_Line__c(
                    Id = ln.Id,
                    Processing_Error__c = 'No active Public Group found for this country’s mapping ' +
                        '(Public_Group_Name__c did not resolve to a Group.DeveloperName).'
                ));
                continue;
            }

            String memberKey = groupId + ':' + userId;
            if (!existingMembershipKeys.contains(memberKey)) {
                membersToInsert.add(new GroupMember(GroupId = groupId, UserOrGroupId = userId));
                existingMembershipKeys.add(memberKey);
            }

            String accessKey = userId + ':' + ln.Country__c;
            User_Country_Access__c existingRow = existingAccessByKey.get(accessKey);
            if (existingRow != null) {
                existingRow.Status__c = 'Active';
                existingRow.Source_Line__c = ln.Id;
                accessRowsToUpsert.add(existingRow);
            } else {
                User_Country_Access__c newRow = new User_Country_Access__c(
                    Requested_User__c = userId,
                    Country__c = ln.Country__c,
                    Status__c = 'Active',
                    Source_Line__c = ln.Id
                );
                accessRowsToUpsert.add(newRow);
                existingAccessByKey.put(accessKey, newRow);
            }

            linesToUpdate.add(new LSO_CCAR_Line__c(Id = ln.Id, Group_Membership_Added__c = true));
        }

        if (!membersToInsert.isEmpty()) {
            Database.insert(membersToInsert, false);
        }
        if (!accessRowsToUpsert.isEmpty()) {
            Database.upsert(accessRowsToUpsert, false);
        }
        if (!linesToUpdate.isEmpty()) {
            Database.update(linesToUpdate, false);
        }
    }
}
